// Login.js
import React, { useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import './Login.css';

function Login() {
    const history = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [loginError, setLoginError] = useState('');

    async function submit(e) {
        e.preventDefault();
        setLoginError('');

        try {
            const res = await axios.post("http://localhost:8000/", {
                email, password,
            });

            if (res.data === "exist") {
                history(`/home?email=${encodeURIComponent(email)}`);
            } else if (res.data === "notexist") {
                setLoginError("User has not signed up.");
            } else {
                setLoginError("An unexpected error occurred.");
            }
        } catch (error) {
            console.error("Login error:", error);
            setLoginError("Invalid credentials. Please try again.");
        }
    }

    return (
        <div className="login-container">
            <div className="login-content">
                <div className="login-box">
                    <div className="logo">DigiBank</div>
                    <h1>Welcome Back!</h1>
                    {loginError && <div className="error-message">{loginError}</div>}

                    <form onSubmit={submit}>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="Email"
                            required
                        />
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Password"
                            required
                        />
                        <input type="submit" value="Login" />
                    </form>
                    <div className="signup-link">
                        <p>New to DigiBank? <Link to="/signup">Sign Up</Link></p>
                    </div>
                </div> {/* Close login-box here */}

                <section className="services-section">
                    <h2>Our Services</h2>
                    <div className="services">
                        <div className="service-card">
                            <span className="icon">🐖</span>
                            <h3>Savings Account</h3>
                            <p>Grow your wealth securely with our high-interest savings accounts.</p>
                        </div>
                        <div className="service-card">
                            <span className="icon">💳</span>
                            <h3>Credit Cards</h3>
                            <p>Flexible credit card options with rewards and cashback offers.</p>
                        </div>
                        <div className="service-card">
                            <span className="icon">📈</span>
                            <h3>Investment Plans</h3>
                            <p>Strategic investment solutions to help you achieve your financial goals.</p>
                        </div>
                    </div>
                </section>
            </div>
        </div>
    );
}

export default Login;
